// Package frontend exposes the production React bundle to the Go application.
//
// The bundle is generated by `npm --prefix app run build`. Keeping the embed
// contract in the root module makes the GUI part of the same distributable as
// the API while development can continue to use Vite directly.
package frontend

import (
	"embed"
	"io/fs"
)

// Dist contains the Vite output rooted at the embedded dist directory.
//
// Use the `all:` pattern because Vite may emit chunks beginning with `_`;
// ordinary embed patterns intentionally omit files with a leading `_` or `.`.
//go:embed all:app/dist
var Dist embed.FS

// Files returns the embedded bundle without the app/dist prefix.
func Files() (fs.FS, error) {
	return fs.Sub(Dist, "app/dist")
}
